//! Visible diplomacy paths from the same actual cell owner as Raw State.
//! Only new entities are serialized as complete new rows; existing historical
//! member maps/option arrays receive actual changed paths and tail edits.
use super::*;
use super::state_columns::OriginalStateColumnsDataV1;
use oasis7_world_state::incremental_diplomacy::{CurrentDiplomacyProjectionDeltaV1,DiplomacyProjectionPathRefV1 as Cell,DiplomacyFieldV1 as Kind};
use oasis7_world_state::observation_projection::current_commitment::{ProjectionColumnDataV1,ProjectionDataPathRefV1 as Path};
use oasis7_formal_protocol::{incremental_execution::{ExecutionTransaction,ExecutionFence},incremental_state::MerkleNodeReader};
use std::{cell::RefCell,mem::size_of};
fn entity_id<'a>(semantic:&'a[u8],common:&mut FormalBoundedContextV1<'_>)->Result<&'a str,BodyMutationError>{common.charge(1,semantic.len()as u64).map_err(paid)?;match oasis7_world_state::incremental_semantic_key::read_semantic_key_v1(semantic).map_err(invalid)?{oasis7_world_state::incremental_semantic_key::SemanticKeyRefV1::Text(v)=>Ok(v),_=>Err(invalid("diplomacy observation entity key"))}}
pub(super) fn fold_diplomacy_observation_v1<M:MerkleNodeReader>(before:&ProjectionColumnDataV1,after_state:&OriginalStateColumnsDataV1,source:&CurrentDiplomacyProjectionDeltaV1,tx:&ExecutionTransaction<'_,M>,max_json:usize,common:&mut FormalBoundedContextV1<'_>,live:&ExecutionFence)->Result<ProjectionColumnDataV1,BodyMutationError>{
 source.validate(tx,common.memory(),live)?;let memory=common.memory().clone();let mut out=before.share_data(&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;let shared=RefCell::new(common);
 source.visit_entities_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|kind,semantic,_key,before,after|{
 let field=kind.name();if !VISIBLE_STATE_COLUMNS_V1.contains(&field){return Ok(())}let collection=match kind{Kind::Alliances=>"members",Kind::Wars=>"participant_outcomes",_=>""};let mut common=shared.borrow_mut();let id=entity_id(semantic,&mut common)?;let old=out.object_member_data(field,&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;let present=match old{Some(old)=>old.object_member_data(id,&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?.is_some(),None=>false};if present!=before{return Err(invalid("diplomacy observation before presence"))}
 if !after{out=out.with_path_data_v1(&[Path::Field(field),Path::Field(id)],None,&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;return Ok(())}
 let rows=after_state.map_data_v1(field,&mut common)?.ok_or_else(||invalid("diplomacy raw rows missing"))?;let record=rows.row_data_v1(semantic,&mut common)?.and_then(|v|v.diplomacy_record_v1()).ok_or_else(||invalid("diplomacy raw current row missing"))?;
 if !before{let meter=RefCell::new(&mut **common);let first=RefCell::new(None);let view=record.serialization_v1(&meter,&first);let json=super::shared_json::capture_shared_v1(&view,&meter,&first,max_json)?;let common=meter.into_inner();let value=super::observation::data(&json,common)?;out=super::observation::ensure_field(&out,field,common)?;out=out.with_path_data_v1(&[Path::Field(field),Path::Field(id)],Some(&value),&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;return Ok(())}
 let capacity=source.entity_patch_count_with_work_v1(kind,semantic,|s,b|common.charge(s,b).map_err(paid))?.ok_or_else(||invalid("diplomacy source entity missing"))?;let n=capacity.checked_mul(size_of::<u64>()).and_then(|n|n.checked_add(size_of::<Vec<u64>>())).ok_or_else(||invalid("diplomacy option staging"))?;common.charge(1,n as u64).map_err(paid)?;let _stage=common.memory().reserve(n,MemoryClass::Ordinary).map_err(ValueTreeError::Memory)?;let mut indices=Vec::with_capacity(capacity);if indices.capacity()!=capacity{return Err(invalid("diplomacy option capacity"))}let mut options_touched=false;
 let inner=RefCell::new(&mut **common);source.visit_entity_patches_with_work_v1(kind,semantic,|s,b|inner.borrow_mut().charge(s,b).map_err(paid),|cell,after|{let mut common=inner.borrow_mut();let path;let mut remove=false;match cell{
 Cell::Member(index)=>{if indices.len()==capacity{return Err(invalid("diplomacy member source bound"))}indices.push(index);options_touched=true;return Ok(())},Cell::Length(_)=>{options_touched=true;return Ok(())},
 Cell::Scalar(name)=>{remove=record.scalar_is_optional_v1(name)?&&after==Some(b"null".as_slice());path=[Path::Field(field),Path::Field(id),Path::Field(name)];}

 }
 let value=if remove{None}else{after.map(|v|super::observation::data(v,&mut common)).transpose()?};out=out.with_path_data_v1(&path,value.as_ref(),&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;Ok::<_,BodyMutationError>(())})?;let common=inner.into_inner();
 if options_touched{let count=indices.len();let logarithm=(usize::BITS-count.max(1).leading_zeros())as usize;let bound=count.checked_mul(logarithm.checked_add(2).ok_or_else(||invalid("diplomacy option sort"))?).and_then(|n|n.checked_mul(16)).ok_or_else(||invalid("diplomacy option sort"))?;common.charge(bound as u64,(count*size_of::<u64>())as u64).map_err(paid)?;let mut stopped=None;indices.sort_unstable_by(|a,b|{if stopped.is_none(){if let Err(error)=common.consume_steps(0){stopped=Some(paid(error));}}a.cmp(b)});if let Some(error)=stopped{return Err(error)}
 let entity=out.object_member_data(field,&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?.ok_or_else(||invalid("diplomacy visible map missing"))?;let entity=entity.object_member_data(id,&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?.ok_or_else(||invalid("diplomacy visible entity missing"))?;let array=entity.object_member_data(collection,&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?.ok_or_else(||invalid("diplomacy options missing"))?;let array=array.share_data(&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;let old_len=array.array_len_data_v1(&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;let new_len=record.members_v1(common)?.len();
 for index in (new_len..old_len).rev(){common.consume_steps(1).map_err(paid)?;out=out.with_path_data_v1(&[Path::Field(field),Path::Field(id),Path::Field(collection),Path::Index(index)],None,&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;}
 let options=record.members_v1(common)?;for index in indices{common.consume_steps(1).map_err(paid)?;let ordinal=usize::try_from(index).map_err(|_|invalid("diplomacy option ordinal"))?;if ordinal>=new_len{continue}let key=super::initial::capture(common,|out|oasis7_world_state::incremental_semantic_key::write_semantic_key_v1(&index,out).map_err(paid))?;let value=options.row_data_v1(&key,common)?.and_then(|v|v.original_value_json()).ok_or_else(||invalid("diplomacy actual option missing"))?;let value=super::observation::data(value,common)?;out=out.with_path_data_v1(&[Path::Field(field),Path::Field(id),Path::Field(collection),Path::Index(ordinal)],Some(&value),&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;}
 }
 Ok::<_,BodyMutationError>(())})?;
 let common=shared.into_inner();for kind in Kind::ALL{let field=kind.name();if VISIBLE_STATE_COLUMNS_V1.contains(&field)&&!after_state.original_field_emitted_v1(field,common)?{out=out.with_object_member_data(field,None,&memory,&mut|s,b|common.charge(s,b)).map_err(super::observation::column_error)?;}}source.validate(tx,common.memory(),live)?;Ok(out)
}
